     7→  ArcElement, PointElement, LineElement,
     8→  Title, Tooltip, Legend,
     9→} from 'chart.js';
    10→import { Bar, Pie } from 'react-chartjs-2';
    11→import { toPng } from 'html-to-image';
    12→import AustriaMap from '../components/AustriaMap';
    13→import type { BezirkStat, Stats } from '../types/stats';
    14→
    15→ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, PointElement, LineElement, Title, Tooltip, Legend);
    16→
    17→export default function ReportsPage() {
    18→  const { id } = useParams<{ id: string }>();
    19→  const [exercise, setExercise] = useState<any>(null);
    20→  const [stats, setStats] = useState<Stats | null>(null);
    21→  const [loading, setLoading] = useState(true);
    22→  const [showParticipants, setShowParticipants] = useState(true);
    23→  const barChartRef = useRef<any>(null);
    24→  const pieChartRef = useRef<any>(null);
    25→  const barCardRef = useRef<HTMLDivElement>(null);
    26→  const pieCardRef = useRef<HTMLDivElement>(null);
    27→  const mapCardRef = useRef<HTMLDivElement>(null);
    28→  const pageRef = useRef<HTMLDivElement>(null);
    29→  const [exporting, setExporting] = useState(false);
    30→
    31→  const createExportHeader = () => {
    32→    const header = document.createElement('div');
    33→    header.setAttribute('data-export-inject', 'true');
    34→    header.style.cssText = 'display:flex;align-items:center;gap:12px;padding:16px 24px;background:#1e3a5f;border-radius:8px;margin-bottom:16px;';
    35→    const img = document.createElement('img');
    36→    img.src = '/bosarsa.jpeg';
    37→    img.style.cssText = 'height:36px;border-radius:4px;';
    38→    header.appendChild(img);
    39→    const text = document.createElement('div');
    40→    const title = document.createElement('div');
    41→    title.textContent = 'BOS-ARSA Log';
    42→    title.style.cssText = 'font-size:16px;font-weight:bold;color:#ffffff;letter-spacing:0.5px;';
    43→    text.appendChild(title);
    44→    const sub = document.createElement('div');
    45→    sub.textContent = 'Im Sinne der Sicherheit';
    46→    sub.style.cssText = 'font-size:10px;color:#93c5fd;letter-spacing:1px;';
    47→    text.appendChild(sub);
    48→    header.appendChild(text);
    49→    return header;
    50→  };
    51→
    52→  const createExportFooter = () => {
    53→    const footer = document.createElement('div');
    54→    footer.setAttribute('data-export-inject', 'true');
    55→    footer.style.cssText = 'text-align:center;padding:12px 0;margin-top:16px;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;';
    56→    footer.textContent = 'oeradio.at  \u00B7  bosarsa.oeradio.at';
    57→    return footer;
    58→  };
    59→
    60→  const downloadChart = async (cardRef: React.RefObject<HTMLDivElement | null>, filename: string) => {
    61→    if (!cardRef.current || !exercise) return;
    62→    setExporting(true);
    63→    const header = createExportHeader();
    64→    const footer = createExportFooter();
    65→    // Wrap the card temporarily
    66→    const wrapper = document.createElement('div');
    67→    wrapper.style.cssText = 'padding:24px;background:#f3f4f6;';
    68→    const parent = cardRef.current.parentNode!;
    69→    const next = cardRef.current.nextSibling;
    70→    parent.insertBefore(wrapper, cardRef.current);
    71→    wrapper.appendChild(header);
    72→    wrapper.appendChild(cardRef.current);
    73→    wrapper.appendChild(footer);
    74→    try {
    75→      const url = await toPng(wrapper, { backgroundColor: '#f3f4f6', pixelRatio: 2 });
    76→      const link = document.createElement('a');
    77→      link.download = filename;
    78→      link.href = url;
    79→      link.click();
    80→    } catch {} finally {
    81→      // Move card back to original position
    82→      if (next) parent.insertBefore(cardRef.current, next); else parent.appendChild(cardRef.current);
    83→      wrapper.remove();
    84→      setExporting(false);
    85→    }
    86→  };
    87→
    88→  const downloadFullPage = async () => {
    89→    if (!pageRef.current || !exercise) return;
    90→    setExporting(true);
    91→    const header = createExportHeader();
    92→    const footer = createExportFooter();
    93→    // Inject header/footer into actual DOM
    94→    pageRef.current.style.padding = '24px';
    95→    pageRef.current.insertBefore(header, pageRef.current.firstChild);
    96→    pageRef.current.appendChild(footer);
    97→    try {
    98→      const url = await toPng(pageRef.current, {
    99→        backgroundColor: '#f3f4f6',
   100→        pixelRatio: 1,
   101→        filter: (node) => {
   102→          if (node instanceof HTMLElement && node.dataset.noExport === 'true') return false;
   103→          return true;
   104→        },
   105→      });
   106→      const link = document.createElement('a');
   107→      link.download = `BOS-ARSA_Auswertung_${exercise.date}.png`;
   108→      link.href = url;
   109→      link.click();
   110→    } catch {} finally {
   111→      header.remove();
   112→      footer.remove();
   113→      if (pageRef.current) pageRef.current.style.padding = '';
   114→      setExporting(false);
   115→    }
   116→  };
   117→
   118→  useEffect(() => {
   119→    if (!id) return;
   120→    Promise.all([
   121→      apiFetch(`/api/v1/exercises/${id}`),
   122→      apiFetch(`/api/v1/exercises/${id}/stats`),
   123→    ]).then(([ex, st]) => {
   124→      setExercise(ex);
   125→      setStats(st);
   126→    }).catch(() => {}).finally(() => setLoading(false));
   127→  }, [id]);
   128→
   129→  if (loading) return <p className="text-gray-500">Laden...</p>;
   130→  if (!exercise) return <p className="text-red-500">Nicht gefunden</p>;
   131→
   132→  // Group bezirk stats by Bundesland
   133→  const byBl: Record<string, { name: string; bezirke: BezirkStat[]; totalParticipants: number; totalReports: number }> = {};
   134→  if (stats) {
   135→    for (const bz of stats.bezirkStats) {
   136→      if (!byBl[bz.bundesland_code]) {
   137→        byBl[bz.bundesland_code] = { name: bz.bundesland, bezirke: [], totalParticipants: 0, totalReports: 0 };
   138→      }
   139→      byBl[bz.bundesland_code].bezirke.push(bz);
   140→      byBl[bz.bundesland_code].totalParticipants += bz.participants;
   141→      byBl[bz.bundesland_code].totalReports += bz.reports;
   142→    }
   143→  }
   144→
   145→  const formatDate = (d: string) => {
   146→    const date = new Date(d + 'T00:00:00');
   147→    return date.toLocaleDateString('de-AT', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
   148→  };
   149→
   150→  return (
   151→    <div ref={pageRef} className="space-y-6">
   152→      <div className="flex items-center justify-between gap-2">
   153→        <div className="min-w-0">
   154→          <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f]">Auswertung</h1>
   155→          <p className="text-xs sm:text-sm text-gray-500 truncate">{exercise.name} — {formatDate(exercise.date)}</p>
   156→        </div>
   157→        <div className="flex items-center gap-2 flex-shrink-0" data-no-export="true">
   158→          <button
   159→            onClick={downloadFullPage}
   160→            disabled={exporting}
   161→            className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm disabled:opacity-50"
   162→          >
   163→            {exporting ? 'Exportieren...' : 'Download Auswertung'}
   164→          </button>
   165→          <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm">
   166→            Zurück
   167→          </Link>
   168→        </div>
   169→      </div>
   170→
   171→      {stats && (
   172→        <>
   173→          {/* Summary cards */}
   174→          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3">
   175→            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   176→              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalParticipants}</div>
   177→              <div className="text-xs sm:text-sm text-gray-500">Teilnehmer</div>
   178→            </div>
   179→            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   180→              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalReports}</div>
   181→              <div className="text-xs sm:text-sm text-gray-500">Rapporte</div>
   182→            </div>
   183→            {stats.perRepeater.map((r) => (
   184→              <div key={r.short_name} className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   185→                <div className="text-xl sm:text-2xl font-bold text-gray-700">{r.count}</div>
   186→                <div className="text-xs text-gray-500 truncate">{r.short_name}</div>
   187→              </div>
   188→            ))}
   189→          </div>
   190→
   191→          {/* Austria Map */}
   192→          {stats.blStats.length > 0 && (
   193→            <div ref={mapCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
   194→              <div className="flex items-center justify-between mb-2 sm:mb-3">
   195→                <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
   196→                  Teilnehmer nach Bundesland / Land
   197→                </h2>
   198→                <button
   199→                  onClick={() => downloadChart(mapCardRef, `BOS-ARSA_Karte_${exercise.date}.png`)}
   200→                  className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
   201→                  title="Karte als PNG herunterladen"
   202→                  data-no-export="true"
   203→                >
   204→                  Download
   205→                </button>
   206→              </div>
   207→              <AustriaMap
   208→                data={stats.blStats.map((bl) => ({
   209→                  code: bl.bundesland_code,
   210→                  participants: bl.participants,
   211→                  reports: bl.reports,
   212→                }))}
   213→              />
   214→            </div>
