        return true;
      },
    });
    const link = document.createElement('a');
    link.download = `BOS-ARSA_Auswertung_${from}_${to}.png`;
    link.href = url;
    link.click();
  } catch {} finally {
    header.remove();
    footer.remove();
    if (pageRef.current) pageRef.current.style.padding = '';
    setExporting(false);
  }
};

