  // Group by Bundesland
  const byBl: Record<string, { name: string; bezirke: BezirkStat[]; totalP: number; totalR: number }> = {};
  for (const bz of bezirkStats) {
    if (!byBl[bz.bundesland_code]) {
      byBl[bz.bundesland_code] = { name: bz.bundesland, bezirke: [], totalP: 0, totalR: 0 };
    }
    byBl[bz.bundesland_code].bezirke.push(bz);
    byBl[bz.bundesland_code].totalP += bz.participants;
    byBl[bz.bundesland_code].totalR += bz.reports;
  }

  for (const [, bl] of Object.entries(byBl)) {
    ensureSpace(doc, 14);
    // BL header row
    doc.save();
    doc.rect(m.left, doc.y, usable, 13).fill(GRAY_100);
    doc.fontSize(7).fillColor('#111827').text(bl.name, colName, doc.y + 3, { bold: true } as any);
    doc.text(String(bl.totalP), colPart, doc.y + 3, { width: 40, align: 'right' });
    doc.text(String(bl.totalR), colRap, doc.y + 3, { width: 40, align: 'right' });
    doc.restore();
    doc.y += 14;

    // Bezirk rows
    bl.bezirke.forEach(bz => {
