// ── Public API ────────────────────────────────────────────

export function generateAggregatedPdf(
  exercises: ExerciseSummary[],
  stats: PdfStats,
  from: string,
  to: string,
): PDFKit.PDFDocument {
  const doc = new PDFDocument({
    layout: 'landscape',
    size: 'A4',
    margins: { top: 30, bottom: 30, left: 40, right: 40 },
    autoFirstPage: true,
    bufferPages: true,
  });

  renderHeader(doc, 'Auswertung', `${formatDateDE(from)} – ${formatDateDE(to)}  ·  ${exercises.length} Übung${exercises.length !== 1 ? 'en' : ''}`);
  renderSummaryCards(doc, stats, exercises.length);
  renderPerRepeater(doc, stats.perRepeater);
  renderExerciseTable(doc, exercises);

  // Visual section: map + charts
  if (stats.blStats.length > 0) {
    doc.addPage();
    renderAustriaMap(doc, stats.blStats);
  }

  const chartData = stats.bezirkStats.length > 0
    ? stats.bezirkStats.map(bz => ({ label: `${bz.bundesland} ${bz.bezirk_code}`, participants: bz.participants, reports: bz.reports }))
    : stats.blStats.map(bl => ({ label: bl.bundesland, participants: bl.participants, reports: bl.reports }));

  if (chartData.length > 0) {
    renderBarChart(doc, chartData);
    renderPieChart(doc, chartData.map(d => ({ label: d.label, value: d.reports })));
  }

  // Tables
  if (stats.bezirkStats.length > 0) {
    doc.addPage();
    renderBezirkTable(doc, stats.bezirkStats, stats);
  } else if (stats.blStats.length > 0) {
    doc.addPage();
    renderBlTable(doc, stats.blStats, stats);
  }

  // Participants
  doc.addPage();
  renderParticipants(doc, stats.participants);

  renderFooter(doc);
  doc.end();
  return doc;
}

export function generateExercisePdf(
  exercise: { name: string; date: string; exercise_type?: string | null },
  stats: PdfStats,
): PDFKit.PDFDocument {
  const doc = new PDFDocument({
    layout: 'landscape',
    size: 'A4',
    margins: { top: 30, bottom: 30, left: 40, right: 40 },
    autoFirstPage: true,
    bufferPages: true,
  });

  const formattedDate = new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT', {
    weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric',
  });
  renderHeader(doc, 'Auswertung', `${exercise.name} — ${formattedDate}`);
  renderSummaryCards(doc, stats);
  renderPerRepeater(doc, stats.perRepeater);

  // Visual section
  if (stats.blStats.length > 0) {
    doc.addPage();
    renderAustriaMap(doc, stats.blStats);
  }

  const chartData = stats.bezirkStats.length > 0
    ? stats.bezirkStats.map(bz => ({ label: `${bz.bundesland} ${bz.bezirk_code}`, participants: bz.participants, reports: bz.reports }))
    : stats.blStats.map(bl => ({ label: bl.bundesland, participants: bl.participants, reports: bl.reports }));

  if (chartData.length > 0) {
    renderBarChart(doc, chartData);
    renderPieChart(doc, chartData.map(d => ({ label: d.label, value: d.reports })));
  }

  // Tables
  if (stats.bezirkStats.length > 0) {
    doc.addPage();
    renderBezirkTable(doc, stats.bezirkStats, stats);
  } else if (stats.blStats.length > 0) {
    doc.addPage();
    renderBlTable(doc, stats.blStats, stats);
  }

  // Participants
  doc.addPage();
  renderParticipants(doc, stats.participants);

  renderFooter(doc);
  doc.end();
  return doc;
}
